import { useEffect } from "react";
import { clearTimerTimeout, clearTimerInterval } from "../arrowNavigationHelper";
export const useClearTimers = ({ action, timeoutTimer, intervalTimer }) => {
    useEffect(() => {
        const clearTimers = () => {
            clearTimerTimeout(timeoutTimer.current);
            clearTimerInterval(intervalTimer.current);
        };
        if (!action) {
            clearTimers();
            timeoutTimer.current = null;
            intervalTimer.current = null;
        }
        return () => { clearTimers(); };
    }, [action, timeoutTimer, intervalTimer]);
};
